//! Names for the canonical hashes: the engine's builtins (from the exe's
//! tables, named where a candidate name hashes to them) and the other
//! names the scripts use (fields, functions, namespaces, locals) that
//! hash from a known identifier. Both generated by `gen/t7gen.py`.

use std::sync::OnceLock;

use rustc_hash::FxHashMap;

pub use super::gen_builtins::BUILTINS;
pub use super::gen_names::NAMES;

/// An engine builtin: its name ("" when not known), argument counts, the
/// handler's address in `BlackOps3.exe`.
#[derive(Clone, Copy, Debug, PartialEq, Eq)]
pub struct Builtin {
    pub hash: u32,
    pub name: &'static str,
    pub min_args: u8,
    pub max_args: u8,
    pub handler: u64,
}

/// The builtin with this hash.
pub fn builtin(hash: u32) -> Option<Builtin> {
    let i = BUILTINS.binary_search_by_key(&hash, |b| b.0).ok()?;
    let (hash, name, min_args, max_args, handler) = BUILTINS[i];
    Some(Builtin { hash, name, min_args, max_args, handler })
}

fn table() -> &'static FxHashMap<u32, &'static str> {
    static T: OnceLock<FxHashMap<u32, &'static str>> = OnceLock::new();
    T.get_or_init(|| BUILTINS.iter().filter(|b| !b.1.is_empty()).map(|b| (b.0, b.1)).chain(NAMES.iter().copied()).collect())
}

/// The name a hash is known by.
pub fn name_of(hash: u32) -> Option<&'static str> {
    table().get(&hash).copied()
}

/// The name a hash is known by, else `#xxxxxxxx` (the form Black Ops III's
/// own messages print unknown hashes in is not known; this one cannot
/// collide with an identifier).
pub fn display(hash: u32) -> String {
    name_of(hash).map_or_else(|| format!("#{hash:08x}"), str::to_owned)
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn known_builtins_and_names() {
        let b = builtin(crate::t7::canon("getentarray")).expect("getentarray");
        assert_eq!(b.name, "getentarray");
        assert!(b.min_args <= b.max_args);
        assert_eq!(name_of(crate::t7::canon("origin")), Some("origin"));
        assert!(BUILTINS.windows(2).all(|w| w[0].0 < w[1].0));
        assert!(NAMES.windows(2).all(|w| w[0].0 < w[1].0));
        assert_eq!(display(0x1234_5678), "#12345678");
    }
}
